function medianSlidingWindow(nums, k) {
  // A binary heap; before(a, b) is true when a belongs above b.
  const makeHeap = (before) => {
    const items = [];
    const swap = (a, b) => ([items[a], items[b]] = [items[b], items[a]]);
    return {
      size: () => items.length,
      top: () => items[0],
      push(value) {
        items.push(value);
        let child = items.length - 1;
        while (child > 0 && before(items[child], items[(child - 1) >> 1])) {
          swap(child, (child - 1) >> 1);
          child = (child - 1) >> 1;
        }
      },
      pop() {
        const top = items[0];
        const last = items.pop();
        if (items.length > 0) items[0] = last;
        let parent = 0;
        for (;;) {
          let next = parent;
          for (const child of [2 * parent + 1, 2 * parent + 2]) {
            if (child < items.length && before(items[child], items[next])) next = child;
          }
          if (next === parent) return top;
          swap(next, parent);
          parent = next;
        }
      },
    };
  };

  const low = makeHeap((a, b) => a > b);
  const high = makeHeap((a, b) => a < b);
  const delayed = new Map();
  let balance = 0;
  const prune = (heap) => {
    while (heap.size() > 0 && delayed.get(heap.top()) > 0) {
      delayed.set(heap.top(), delayed.get(heap.top()) - 1);
      heap.pop();
    }
  };

  const medians = [];
  for (let i = 0; i < nums.length; i++) {
    if (low.size() === 0 || nums[i] <= low.top()) {
      low.push(nums[i]);
      balance++;
    } else {
      high.push(nums[i]);
      balance--;
    }
    if (i >= k) {
      const out = nums[i - k];
      delayed.set(out, (delayed.get(out) ?? 0) + 1);
      balance += out <= low.top() ? -1 : 1;
    }
    if (balance > 1) {
      high.push(low.pop());
      balance -= 2;
    } else if (balance < 0) {
      low.push(high.pop());
      balance += 2;
    }
    prune(low);
    prune(high);
    if (i >= k - 1) {
      medians.push(k % 2 === 1 ? low.top() : (low.top() + high.top()) / 2);
    }
  }
  return medians;
}

