function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const MIN = -2147483648, MAX = 2147483647;
  const large = size === 'large';
  const n = large ? 1500 + pick(501) : 1 + pick(10);
  const k = large ? [1, 2, 3, 50, 501, 1000, n][pick(7)] : 1 + pick(n);
  const style = pick(4);
  const value = () => {
    if (style === 0) return pick(7) - 3;
    if (style === 1) return [MIN, MAX, 0, -1, 1][pick(5)];
    if (style === 2) return pick(2001) - 1000;
    return MIN + pick(2 ** 32);
  };
  return [Array.from({ length: n }, value), k];
}
